export const STEINER_1911_EVIDENCE =
  "Rudolf Steiner, The Submerged Continents of Atlantis and Lemuria (London: Theosophical Publishing Society, 1911), 'authorized translation from the German', edited by Max Gysi. Public domain in the United States (published 1911); Gysi's death date was not established, so its status elsewhere is not settled here. Taken from the Rudolf Steiner Archive's transcription (rsarchive.org, GA011/English/TPS1911), compared word by word with an earlier state of the same transcription (archive.org ste-11_202012, a print-out of 2011, read through its OCR) and with the four phrases quoted in The Bookman, September 1911. Only one transcription of the 1911 English could be reached, and no page image of the book: the two states of the e-text are not independent copies, so no reading could be settled by a majority of independent witnesses or checked on a page. Two errors common to both states were corrected by hand on the sense and the German, and two readings are left disputed; all are listed in scripts/texts/steiner-atlantis.py. The earlier state's paragraph breaks are restored inside the Archive's numbered paragraphs; italic is not marked, and the book's footnotes are printed after the text as '[Footnote]'.";

function englishLayer(section: SteinerSection): CorpusLayer {
  return {
    key: "eng-1911",
    layer: "translation",
    sourceKey: "steiner-atlantis-lemuria-1911",
    content: section.text,
    language: "English",
    licence: "public_domain_us",
    evidence: `${STEINER_1911_EVIDENCE} (chapter ${NUMERALS[section.chapter]}, the Archive's paragraphs [${section.paragraphs}])`,
  };
}

