function chapterPassage(chapter: number): CorpusPassage {
  const meta = CHAPTERS[chapter];
  const key = `${BOOK}.${chapter}`;
  return {
    key,
    parentKey: BOOK,
    divisionKind: "chapter",
    label: meta.label,
    reference: `Atlantis and Lemuria (London, 1911), chapter ${NUMERALS[chapter]}, '${STEINER_CHAPTER_TITLES[chapter]}'; German: '${meta.german}' (GA 11)`,
    sourceKey: "steiner-atlantis-lemuria-1911",
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [],
    images: imagesFor(STEINER_IMAGES, key),
  };
}

function sectionPassage(section: SteinerSection): CorpusPassage {
  const id = `${section.chapter}.${section.section}`;
  const meta = SECTIONS[id];
  const key = `${BOOK}.${id}`;
  const where = section.chapter === 5 ? "paragraphs numbered on from chapter IV" : "paragraphs";
  return {
    key,
    parentKey: `${BOOK}.${section.chapter}`,
    divisionKind: "section",
    label: meta.label,
    reference: `Atlantis and Lemuria (London, 1911), chapter ${NUMERALS[section.chapter]}, '${STEINER_CHAPTER_TITLES[section.chapter]}', the Rudolf Steiner Archive's ${where} [${section.paragraphs}]`,
    sourceKey: "steiner-atlantis-lemuria-1911",
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [englishLayer(section)],
    themes: meta.themes?.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(STEINER_IMAGES, key),
  };
}

function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [
    {
      key: BOOK,
      divisionKind: "book",
      label: "The Submerged Continents of Atlantis and Lemuria (English, 1911)",
      reference:
        "The Submerged Continents of Atlantis and Lemuria, Their History and Civilization, Being Chapters from the Akashic Records (London: Theosophical Publishing Society, 1911), chapters I–X",
      sourceKey: "steiner-atlantis-lemuria-1911",
      summary:
        "The first English of Steiner's articles 'Aus der Akasha-Chronik': an account, which he says he read in the Akashic Records, of the Atlantean and Lemurian root races and, going further back, of the first human beings, the separation of the sexes and the departure of the sun and moon from the earth.",
      notes:
        "The English covers the first part of the German book only, to 'Austritt des Mondes'. Steiner names W. Scott-Elliot's The Story of Atlantis (1896) for the outer history of Atlantis and the 'Secret Doctrine' for the root races, and cites 'Theosophical literature' for the Lemurian continent, the Manu, the Polar and Hyperborean races, Prâna and Kâma; he wrote the articles while General Secretary of the German Section of the Theosophical Society. The book ranks human groups as advanced or 'degraded' races; that racial theory is the text's own.",
      verificationStatus: "unverified",
      layers: CITED,
      dates: DATES,
      images: imagesFor(STEINER_IMAGES, BOOK),
    },
  ];
  for (let chapter = 1; chapter <= 10; chapter++) {
    passages.push(chapterPassage(chapter));
    for (const section of STEINER_SECTIONS.filter((s) => s.chapter === chapter)) passages.push(sectionPassage(section));
  }
  return passages;
}

